// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am) public {
        vm.assume(_val < 1e30);
        vm.assume(_lockTime < 1e9);
        vm.assume(_am < 1e30);

        // Initialize the contract: first set MinSum, then call Initialized.
        c.SetMinSum(_val);
        c.Initialized();

        uint expected = c.MinSum();

        // Try a Collect call with some sent value to trigger potential changes
        address payable user = payable(address(0x1234));
        vm.deal(user, 1 ether);
        vm.prank(user);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("Collect(uint256)", _am));

        // The rule: SetMinSum must equal the value set before Initialized
        assertTrue(c.MinSum() == expected);
    }
}

